/**
 * generated by stackra gen from src/config/seo.config.ts (sitemaps), src/config/i18n.config.ts
 * (locales) and gen/sitemap.ts — do not edit
 * Purpose: `/sitemaps/<source>.xml`: the URLs of one source, each with hreflang alternates for
 *          every locale and image entries where the source provides them.
 * Boundary: alternates come from the one helper every page's head uses, so links and sitemaps never
 *           disagree.
 * Runtime: worker
 */
import { routeContext } from "@stackra/navigation/router";
import { writeSitemap } from "@stackra/seo/sitemap";
import type { Route } from "./+types/sitemap.route";
import { sitemapSources } from "#stackra/sitemap";
import { alternates } from "#src/server/alternates.server";
import { resolveSite } from "#src/server/resolve-site.server";

export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args);
  const site = await resolveSite(ctx);
  const source = sitemapSources[args.params.source.replace(/\.xml$/, "")];
  if (!source || !site.indexable) return new Response(null, { status: 404 });
  const items = await source.list(ctx.clients, site, ctx.href);
  const entries = items.map((item) => {
    const urls = alternates(ctx, item.path);
    return {
      loc: urls["x-default"],
      lastmod: item.updatedAt,
      changefreq: source.changefreq,
      alternates: urls,
      images: item.image ? [item.image] : [],
    };
  });
  return new Response(writeSitemap(entries), {
    headers: {
      "Content-Type": "application/xml; charset=utf-8",
      "Cache-Control": "public, max-age=3600",
    },
  });
}
